# owner: platform
"""Plain text absence notices for parents."""

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from typing import Iterable, List
from datetime import date


def stray_ids(
    student: Student, items: List[Mark]
) -> List[str]:
    """Ids on marks that are not the student's."""
    return sorted(
        {item.student_id for item in items}
        - {student.student_id}
    )


def absent_days(
    student: Student, items: List[Mark]
) -> List[date]:
    """Distinct absent days, oldest first."""
    strays = stray_ids(student, items)
    if strays:
        raise ValueError(f"other students: {strays}")
    return sorted(set(days_missed(items)))


def join_days(days: List[date]) -> str:
    return ", ".join(day.isoformat() for day in days)


def compose(student: Student, days: List[date]) -> str:
    count = len(days)
    unit = "day" if count == 1 else "days"
    return (
        f"{student.first_name} {student.last_name} missed "
        f"{count} {unit} of school: {join_days(days)}."
    )


def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short notice naming the student and absent days."""
    days = absent_days(student, list(marks))
    if not days:
        raise ValueError("no absences to report")
    return compose(student, days)

