# owner: platform
import unittest
from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("7", "Rivera", "Ana", "A")


def mark(day, status="absent", who="7"):
    return Mark(who, date(2026, 9, day), status)


class BuildNoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        text = build_notice(
            PUPIL, [mark(9), mark(2), mark(5, "present")]
        )
        self.assertIn("Ana Rivera", text)
        self.assertIn("2 days", text)
        self.assertIn("2026-09-02, 2026-09-09", text)

    def test_single_day(self):
        text = build_notice(PUPIL, [mark(3)])
        self.assertIn("1 day of", text)

    def test_excused_not_counted(self):
        text = build_notice(
            PUPIL, [mark(3), mark(4, "excused")]
        )
        self.assertNotIn("2026-09-04", text)

    def test_other_student(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(3), mark(4, who="8")])

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(3, "late")])
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [])
